CREATE OR REPLACE FUNCTION app_security.impl_admin_phone_catalogue(p_kind text, p_entry jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid:=coalesce((p_entry->>'id')::uuid,gen_random_uuid()); aliases text[]; begin
 if not app_security.is_active_staff_aal2('content_editor') or not app_security.has_current_policy_acceptance(auth.uid()) then raise exception using errcode='42501',message='Staff MFA and policy acceptance required'; end if;
 if p_kind not in ('brand','model') or p_entry-array['id','name','aliases','enabled','sort_order','brand_id','older_group','other']<>'{}'::jsonb then raise exception 'Invalid catalogue input'; end if;
 select coalesce(array_agg(trim(value)),'{}') into aliases from jsonb_array_elements_text(p_entry->'aliases');
 if exists(select 1 from unnest(aliases) a where length(a) not between 1 and 100) then raise exception 'Invalid alias'; end if;
 if p_kind='brand' then
  insert into public.phone_brands(id,name,aliases,enabled,sort_order) values(target,trim(p_entry->>'name'),aliases,(p_entry->>'enabled')::boolean,(p_entry->>'sort_order')::integer)
  on conflict(id) do update set name=excluded.name,aliases=excluded.aliases,enabled=excluded.enabled,sort_order=excluded.sort_order,updated_at=clock_timestamp();
 else
  insert into public.phone_models(id,brand_id,name,aliases,enabled,sort_order,older_group,other) values(target,(p_entry->>'brand_id')::uuid,trim(p_entry->>'name'),aliases,(p_entry->>'enabled')::boolean,(p_entry->>'sort_order')::integer,(p_entry->>'older_group')::boolean,(p_entry->>'other')::boolean)
  on conflict(id) do update set name=excluded.name,aliases=excluded.aliases,enabled=excluded.enabled,sort_order=excluded.sort_order,older_group=excluded.older_group,other=excluded.other,updated_at=clock_timestamp();
 end if;
 perform app_security.log_audit_event('catalogue.phone_updated','phone_'||p_kind,target,jsonb_build_object('enabled',p_entry->'enabled'));
 return jsonb_build_object('success',true);
end $function$

CREATE OR REPLACE FUNCTION app_security.impl_fulfill_data_export_base(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_req record;
  v_target_user_id uuid;
  v_profile jsonb;
  v_account jsonb;
  v_listings jsonb;
  v_favourites jsonb;
  v_reports jsonb;
  v_support_tickets jsonb;
  v_sent_messages jsonb;
  v_policy_acceptances jsonb;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_req
  FROM public.privacy_requests
  WHERE id = p_request_id AND request_type = 'export_data';

  IF v_req IS NULL THEN
    RAISE EXCEPTION 'Export privacy request not found';
  END IF;

  -- Caller must be owner OR active administrator with AAL2
  IF v_req.user_id <> v_caller_id AND NOT app_security.is_active_staff_aal2('administrator') THEN
    RAISE EXCEPTION 'Forbidden: not authorized to export this data';
  END IF;

  v_target_user_id := v_req.user_id;

  -- 1. Profile Data
  SELECT to_jsonb(p) INTO v_profile
  FROM (
    SELECT id, display_name, bio, city, state, created_at, updated_at
    FROM public.profiles
    WHERE id = v_target_user_id
  ) p;

  -- 2. Account Metadata with acceptance audit fields
  SELECT to_jsonb(ua) INTO v_account
  FROM (
    SELECT user_id, terms_accepted_at, terms_version, privacy_policy_version,
           acceptable_use_version, age_confirmed_at, minimum_age_confirmed,
           notification_preferences, created_at
    FROM public.user_accounts
    WHERE user_id = v_target_user_id
  ) ua;

  -- 3. Listings Data
  SELECT COALESCE(jsonb_agg(l), '[]'::jsonb) INTO v_listings
  FROM (
    SELECT id, title, description, condition, price_type, price_paise, status, category_attributes, created_at, published_at
    FROM public.listings
    WHERE seller_id = v_target_user_id
    ORDER BY created_at DESC
  ) l;

  -- 4. Favourites Data
  SELECT COALESCE(jsonb_agg(f), '[]'::jsonb) INTO v_favourites
  FROM (
    SELECT listing_id, created_at
    FROM public.favourites
    WHERE user_id = v_target_user_id
    ORDER BY created_at DESC
  ) f;

  -- 5. User Submitted Reports
  SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_reports
  FROM (
    SELECT id, target_type, target_id, reason, details, status, created_at, resolved_at
    FROM public.reports
    WHERE reporter_id = v_target_user_id
    ORDER BY created_at DESC
  ) r;

  -- 6. User Support Tickets & Non-Internal Messages
  SELECT COALESCE(jsonb_agg(t), '[]'::jsonb) INTO v_support_tickets
  FROM (
    SELECT st.id, st.category, st.subject, st.status, st.created_at,
      (
        SELECT COALESCE(jsonb_agg(m), '[]'::jsonb)
        FROM (
          SELECT id, sender_id, content, created_at
          FROM public.support_messages sm
          WHERE sm.ticket_id = st.id AND sm.is_internal_note = false
          ORDER BY sm.created_at ASC
        ) m
      ) AS messages
    FROM public.support_tickets st
    WHERE st.user_id = v_target_user_id
    ORDER BY st.created_at DESC
  ) t;

  -- 7. User Sent Messages (Counterparty details strictly redacted)
  SELECT COALESCE(jsonb_agg(m), '[]'::jsonb) INTO v_sent_messages
  FROM (
    SELECT id, conversation_id, content, created_at
    FROM public.messages
    WHERE sender_id = v_target_user_id
    ORDER BY created_at DESC
  ) m;

  -- 8. Historical Policy Re-acceptance Records
  SELECT COALESCE(jsonb_agg(par), '[]'::jsonb) INTO v_policy_acceptances
  FROM (
    SELECT id, terms_version, privacy_policy_version, acceptable_use_version, minimum_age_confirmed, accepted_at
    FROM public.policy_acceptance_records
    WHERE user_id = v_target_user_id
    ORDER BY accepted_at ASC
  ) par;

  -- Update request status to resolved
  UPDATE public.privacy_requests
  SET status = 'resolved',
      resolved_at = pg_catalog.clock_timestamp(),
      resolved_by = v_caller_id,
      resolution_notes = 'Data export generated and delivered.'
  WHERE id = p_request_id;

  -- Log audit event
  PERFORM app_security.log_audit_event(
    'privacy.export_fulfilled',
    'privacy_requests',
    p_request_id,
    jsonb_build_object('target_user_id', v_target_user_id, 'downloader', v_caller_id)
  );

  RETURN jsonb_build_object(
    'export_id', p_request_id,
    'generated_at', pg_catalog.clock_timestamp(),
    'profile', v_profile,
    'account', v_account,
    'listings', v_listings,
    'favourites', v_favourites,
    'reports', v_reports,
    'support_tickets', v_support_tickets,
    'sent_messages', v_sent_messages,
    'policy_acceptances', v_policy_acceptances
  );
END;
$function$

CREATE OR REPLACE FUNCTION app_security.impl_posting_v2_cleanup(operation text, session_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.posting_upload_sessions; items jsonb:='[]'; begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception using errcode='42501',message='Cleanup service required'; end if;
 if operation='ack' then
  delete from public.posting_upload_sessions where id=session_id and state in ('expired','submitted') and cleanup_after<=now();return '[]';
 elsif operation<>'claim' then raise exception 'Invalid cleanup operation'; end if;
 for s in select * from public.posting_upload_sessions where cleanup_after<=now() and state<>'cleaned' order by cleanup_after,id limit 50 for update skip locked loop
  if s.state<>'submitted' then update public.posting_upload_sessions set state='expired' where id=s.id; end if;
  items:=items||jsonb_build_array(jsonb_build_object('id',s.id,'owner_id',s.owner_id,'listing_id',s.listing_id,'submitted',s.state='submitted',
   'attached',coalesce((select jsonb_agg(id) from public.listing_media where listing_id=s.listing_id),'[]'::jsonb),
   'media',coalesce((select jsonb_agg(jsonb_build_object('id',id,'attempt',attempt)) from public.posting_staged_media where posting_staged_media.session_id=s.id),'[]'::jsonb)));
 end loop;
 return items;
end $function$

CREATE OR REPLACE FUNCTION app_security.impl_posting_v2_media_ready(session_id uuid, media_id uuid, attempt_id uuid, file_size integer, width integer, height integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.posting_upload_sessions; m public.posting_staged_media; begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception using errcode='42501',message='Media service required'; end if;
 select * into s from public.posting_upload_sessions where id=session_id for update;
 if s.state is distinct from 'open' or s.expires_at<=now() then return false; end if;
 if exists(select 1 from public.posting_staged_media x where x.session_id=s.id and x.id=media_id and x.attempt=attempt_id and x.state='ready' and x.file_size=impl_posting_v2_media_ready.file_size and x.width=impl_posting_v2_media_ready.width and x.height=impl_posting_v2_media_ready.height) then return true; end if;
 update public.posting_staged_media x set state='ready',file_size=impl_posting_v2_media_ready.file_size,width=impl_posting_v2_media_ready.width,height=impl_posting_v2_media_ready.height
 where x.id=media_id and x.session_id=s.id and x.attempt=attempt_id and x.state='uploading' returning * into m;
 return m.id is not null;
end $function$

CREATE OR REPLACE FUNCTION app_security.impl_posting_v2_session(p_session_id uuid, p_operation text, p_media_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=app_security.posting_v2_actor(); s public.posting_upload_sessions; m public.posting_staged_media; n integer;
begin
 if p_operation='create' then
  perform pg_advisory_xact_lock(hashtextextended(u::text,2));
  if not exists(select 1 from public.posting_category_definitions where category_key='mobiles' and subcategory_key='mobile-phones' and version=2 and enabled) then raise exception 'Posting unavailable'; end if;
  if (select count(*) from public.posting_upload_sessions where owner_id=u and state in ('open','finalizing') and expires_at>now())>=5 and not exists(select 1 from public.posting_upload_sessions where id=p_session_id and owner_id=u) then raise exception 'Too many upload sessions'; end if;
  insert into public.posting_upload_sessions(id,owner_id) values(p_session_id,u) on conflict(id) do nothing;
 end if;
 select * into s from public.posting_upload_sessions where id=p_session_id and owner_id=u for update;
 if s.id is null then raise exception using errcode='42501',message='Upload session unavailable'; end if;
 if s.state='submitted' then return jsonb_build_object('session',to_jsonb(s),'media','[]'::jsonb); end if;
 if s.expires_at<=now() or s.state in ('expired','cleaned') then raise exception 'Upload session expired'; end if;
 if p_operation in ('reserve','remove') then
  if s.expires_at<now()+interval '5 minutes' then raise exception 'Upload session is expiring; start a new posting'; end if;
  if s.state<>'open' then raise exception 'Submission is being finalized'; end if;
  if p_operation='remove' then
   update public.posting_staged_media set state='removed' where id=p_media_id and session_id=s.id;
  else
   select * into m from public.posting_staged_media where id=p_media_id and session_id=s.id for update;
   if m.state='removed' then raise exception 'Photo removed'; end if;
   if m.id is null then
    select count(*) into n from public.posting_staged_media where session_id=s.id and state<>'removed';
    if n>=8 then raise exception 'Maximum 8 photos'; end if;
    insert into public.posting_staged_media(id,session_id) values(p_media_id,s.id) returning * into m;
   elsif m.state='uploading' then
    if m.lease_until>now() then raise exception using errcode='PT409',message='Upload in progress; retry shortly'; end if;
    update public.posting_staged_media set attempt=gen_random_uuid(),lease_until=now()+interval '2 minutes' where id=m.id returning * into m;
   end if;
  end if;
 elsif p_operation='prepare' then
  if exists(select 1 from public.posting_staged_media where session_id=s.id and state='uploading') then raise exception 'Finish or remove failed uploads first'; end if;
  update public.posting_upload_sessions set state='finalizing',cleanup_after=greatest(cleanup_after,now()+interval '10 minutes') where id=s.id returning * into s;
 elsif p_operation not in ('create','read') then raise exception 'Invalid operation';
 end if;
 return jsonb_build_object('session',to_jsonb(s),'media',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.id) from public.posting_staged_media x where x.session_id=s.id and x.state<>'removed'),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION app_security.impl_seller_transition_listing(p_listing_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_listing record;
  v_new_status public.listing_status_enum;
  v_renewal_limit constant integer := 3;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF app_security.get_account_status(v_caller_id) != 'active' THEN
    RAISE EXCEPTION 'account is not active';
  END IF;

  IF NOT app_security.has_current_policy_acceptance(v_caller_id) THEN
    RAISE EXCEPTION 'POLICY_ACCEPTANCE_REQUIRED: Re-acceptance of Public Beta policies is required';
  END IF;

  SELECT * INTO v_listing
  FROM public.listings
  WHERE id = p_listing_id
  FOR UPDATE;

  IF v_listing.id IS NULL THEN
    RAISE EXCEPTION 'listing not found';
  END IF;

  IF v_listing.seller_id != v_caller_id THEN
    RAISE EXCEPTION 'caller does not own this listing';
  END IF;

  CASE p_action
    WHEN 'pause' THEN
      IF v_listing.status != 'active' THEN
        RAISE EXCEPTION 'only active listings can be paused (current: %)', v_listing.status;
      END IF;
      v_new_status := 'paused'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.paused',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'resume' THEN
      IF v_listing.status != 'paused' THEN
        RAISE EXCEPTION 'only paused listings can be resumed (current: %)', v_listing.status;
      END IF;
      IF v_listing.published_at IS NULL THEN
        RAISE EXCEPTION 'unapproved listing cannot be resumed';
      END IF;
      IF v_listing.expires_at IS NOT NULL AND v_listing.expires_at <= pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION 'expired listing cannot be resumed directly';
      END IF;
      v_new_status := 'active'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.resumed',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'reserve' THEN
      IF v_listing.status != 'active' THEN
        RAISE EXCEPTION 'only active listings can be reserved (current: %)', v_listing.status;
      END IF;
      v_new_status := 'reserved'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.reserved',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'unreserve' THEN
      IF v_listing.status != 'reserved' THEN
        RAISE EXCEPTION 'only reserved listings can be unreserved (current: %)', v_listing.status;
      END IF;
      v_new_status := 'active'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.unreserved',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'mark_sold' THEN
      IF v_listing.status NOT IN ('active', 'reserved', 'paused') THEN
        RAISE EXCEPTION 'listing in status % cannot be marked sold', v_listing.status;
      END IF;
      v_new_status := 'sold'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          sold_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.sold',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision)
      );

    WHEN 'renew' THEN
      IF v_listing.status != 'expired' THEN
        RAISE EXCEPTION 'only expired listings can be renewed (current: %)', v_listing.status;
      END IF;
      IF v_listing.renewal_count >= v_renewal_limit THEN
        RAISE EXCEPTION 'renewal limit of % reached', v_renewal_limit;
      END IF;
      v_new_status := 'pending_review'::public.listing_status_enum;

      UPDATE public.listings
      SET status = v_new_status,
          renewal_count = v_listing.renewal_count + 1,
          submitted_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
      WHERE id = p_listing_id;

      PERFORM app_security.log_audit_event(
        'listing.renewed',
        'listings',
        p_listing_id,
        jsonb_build_object('revision', v_listing.revision, 'renewal_count', v_listing.renewal_count + 1)
      );

    ELSE
      RAISE EXCEPTION 'invalid transition action: %', p_action;
  END CASE;

  RETURN jsonb_build_object('success', true, 'new_status', v_new_status);
END;
$function$

CREATE OR REPLACE FUNCTION app_security.is_active_staff_aal2(p_required_role staff_role_enum)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
  v_user_role public.staff_role_enum;
  v_status public.account_status_enum;
  v_aal text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  -- 1. Check account status is active
  SELECT account_status INTO v_status
  FROM public.user_accounts
  WHERE user_id = v_user_id;

  IF v_status IS DISTINCT FROM 'active' THEN
    RETURN false;
  END IF;

  -- 2. Check JWT assurance level claim is aal2
  v_aal := (auth.jwt() ->> 'aal');
  IF v_aal IS DISTINCT FROM 'aal2' THEN
    RETURN false;
  END IF;

  -- 3. Check staff role assignment
  SELECT role INTO v_user_role
  FROM public.staff_roles
  WHERE user_id = v_user_id;

  IF v_user_role IS NULL THEN
    RETURN false;
  END IF;

  -- Administrators satisfy all role requirements
  IF v_user_role = 'administrator' THEN
    RETURN true;
  END IF;

  RETURN v_user_role = p_required_role;
END;
$function$
